<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/bootstrap.php'; require_admin();
$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
if($id===false){http_response_code(404);exit('Enquiry not found.');}
$db=database_connection();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??null))$error='This page expired. Refresh and try again.';
 else{
  $action=(string)($_POST['action']??'');
  if($action==='reply'){$body=trim((string)($_POST['body']??''));if($body===''||text_length($body)>3000)$error='Write a reply under 3,000 characters.';else{$q=$db->prepare("INSERT INTO lead_messages (lead_id,sender_type,body) VALUES (:id,'admin',:body)");$q->execute(['id'=>$id,'body'=>$body]);$db->prepare("UPDATE leads SET status='contacted' WHERE id=:id")->execute(['id'=>$id]);header('Location: lead?id='.(int)$id.'&replied=1',true,303);exit;}}
  elseif($action==='assign'){$expert=filter_var($_POST['expert_id']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($expert!==false){$check=$db->prepare('SELECT id FROM experts WHERE id=:id AND active=1');$check->execute(['id'=>$expert]);if(!$check->fetchColumn())$expert=null;}else $expert=null;$q=$db->prepare('UPDATE leads SET expert_id=:expert WHERE id=:id');$q->execute(['expert'=>$expert,'id'=>$id]);$notice='Expert assignment updated.';}
  else $error='That action was not recognised.';
 }
}
$q=$db->prepare('SELECT l.*,e.name AS expert_name,e.specialty AS expert_specialty FROM leads l LEFT JOIN experts e ON e.id=l.expert_id WHERE l.id=:id');$q->execute(['id'=>$id]);$lead=$q->fetch();if(!$lead){http_response_code(404);exit('Enquiry not found.');}
$db->prepare("UPDATE lead_messages SET is_read=1 WHERE lead_id=:id AND sender_type='student'")->execute(['id'=>$id]);
$messages=$db->prepare('SELECT sender_type,body,created_at FROM lead_messages WHERE lead_id=:id ORDER BY created_at,id');$messages->execute(['id'=>$id]);$messages=$messages->fetchAll();
$experts=$db->query('SELECT id,name,specialty FROM experts WHERE active=1 ORDER BY name')->fetchAll();
if(isset($_GET['replied']))$notice='Reply sent. It will appear in the student account.';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Student conversation · You Aspirant admin</title><link rel="stylesheet" href="../styles.css"><link rel="stylesheet" href="admin.css"><link rel="stylesheet" href="../features.css"></head><body class="admin-body"><header class="dashboard-header"><a class="admin-brand" href="/admin"><span class="brand-mark"><span>Y</span></span><span><strong>you aspirant</strong><small>Student conversation</small></span></a><a class="logout-button" href="/admin">← Inbox</a></header><?php require __DIR__.'/_nav.php';?><main class="dashboard-main"><div class="dashboard-title"><div><p class="admin-eyebrow">Enquiry #<?=(int)$lead['id']?></p><h1><?=escape_html($lead['name'])?></h1><p class="dashboard-subtitle"><a href="mailto:<?=escape_html($lead['email'])?>"><?=escape_html($lead['email'])?></a> · <?=escape_html($lead['interest'])?> · <?=escape_html(date('M j, Y g:i a',strtotime((string)$lead['created_at'])))?></p></div><span class="status-pill status-<?=escape_html($lead['status'])?>"><?=escape_html($lead['status'])?></span></div><?php if($notice):?><p class="admin-notice"><?=escape_html($notice)?></p><?php endif;?><?php if($error):?><p class="admin-error"><?=escape_html($error)?></p><?php endif;?><div class="conversation-layout"><section class="feature-panel"><h2>Conversation</h2><?php if(trim((string)$lead['message'])!==''):?><article class="chat-message chat-student"><strong>Original enquiry</strong><p><?=nl2br(escape_html($lead['message']))?></p><small><?=escape_html(date('M j, g:i a',strtotime((string)$lead['created_at'])))?></small></article><?php endif;?><?php foreach($messages as $message):?><article class="chat-message chat-<?=escape_html($message['sender_type'])?>"><strong><?=$message['sender_type']==='admin'?'You Aspirant team':escape_html($lead['name'])?></strong><p><?=nl2br(escape_html($message['body']))?></p><small><?=escape_html(date('M j, g:i a',strtotime((string)$message['created_at'])))?></small></article><?php endforeach;?><form class="reply-form" method="post"><input type="hidden" name="csrf_token" value="<?=escape_html(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$id?>"><input type="hidden" name="action" value="reply"><label>Your reply<textarea name="body" maxlength="3000" rows="5" required></textarea></label><button class="button button-dark" type="submit">Send reply ↗</button><p class="feature-muted">The student will see this in their account dashboard.</p></form></section><aside class="feature-panel"><h2>Assign an expert</h2><form class="feature-form" method="post"><input type="hidden" name="csrf_token" value="<?=escape_html(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$id?>"><input type="hidden" name="action" value="assign"><label>Expert<select name="expert_id"><option value="">No expert assigned</option><?php foreach($experts as $expert):?><option value="<?=(int)$expert['id']?>" <?=(int)$lead['expert_id']===(int)$expert['id']?'selected':''?>><?=escape_html($expert['name'])?> · <?=escape_html($expert['specialty'])?></option><?php endforeach;?></select></label><button class="button button-dark" type="submit">Save assignment ↗</button></form><p class="feature-help">Use the student’s selected service (“<?=escape_html($lead['interest'])?>”) to choose a matching specialty.</p><?php if(!$lead['user_id']):?><p class="feature-muted">This enquiry was sent before the student signed in. Replies are only visible in student accounts for enquiries linked to that account.</p><?php endif;?></aside></div></main></body></html>
